/**
 * SourceCategory
 *
 * What *kind* of source this is (classified by the compress LLM), independent
 * of TrustSourceType (how authoritative it is for a specific claim). Deliberately
 * uses "official" rather than "primary" so the two axes can never collide.
 *
 * Also doubles as the sub-question's ``source_intent`` (what kind of source a
 * question *needs*) — the two concepts overlap enough that a single enum lets
 * ``classify_source_importance`` compare "what we got" against "what we asked
 * for" directly.
 */
export type SourceCategory = 'official' | 'news' | 'social' | 'academic' | 'aggregator' | 'marketplace' | 'other';

